/**
 * Channel icon manifest published by the Chatwoot web app at
 * `<installation url>/channel-icons.json` (generated by the web repo's
 * `scripts/generate-channel-icons.mjs`). It carries the same glyphs the web
 * dashboard draws, so the mobile app can show identical channel logos.
 */

export type IconifyIcon = { body: string; width: number; height: number };

export type ChannelIconManifest = {
  version: string;
  /** Monochrome glyph name per channel type. */
  line: Record<string, string>;
  /** Full-colour brand glyph name per channel type. */
  brand: Record<string, string>;
  providerLine: Record<string, string>;
  providerBrand: Record<string, string>;
  voice: { twilio?: string; whatsapp?: string };
  twilioWhatsapp: string;
  fallback: string;
  /** Glyph name -> Iconify icon data. */
  icons: Record<string, IconifyIcon>;
};

export type ChannelIconTarget = {
  channelType?: string;
  medium?: string;
  /** Email provider, e.g. `google` or `microsoft`. */
  provider?: string;
  /** Legacy mobile marker: Instagram DMs arrive on a Facebook page inbox. */
  additionalType?: string;
  voiceEnabled?: boolean;
};

const WHATSAPP = 'Channel::Whatsapp';
const TWILIO = 'Channel::TwilioSms';
const EMAIL = 'Channel::Email';
const INSTAGRAM = 'Channel::Instagram';
const FACEBOOK = 'Channel::FacebookPage';

// A manifest is only a few dozen icons. Anything much bigger is not ours.
export const MAX_MANIFEST_BYTES = 512 * 1024;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const isStringMap = (value: unknown): value is Record<string, string> =>
  isRecord(value) && Object.values(value).every(entry => typeof entry === 'string');

const isIcon = (value: unknown): value is IconifyIcon =>
  isRecord(value) &&
  typeof value.body === 'string' &&
  typeof value.width === 'number' &&
  typeof value.height === 'number' &&
  value.width > 0 &&
  value.height > 0;

/** Narrows untrusted JSON (network or cache) to a usable manifest. */
export const isChannelIconManifest = (value: unknown): value is ChannelIconManifest => {
  if (!isRecord(value)) return false;
  return (
    typeof value.version === 'string' &&
    isStringMap(value.line) &&
    isStringMap(value.brand) &&
    isStringMap(value.providerLine) &&
    isStringMap(value.providerBrand) &&
    isStringMap(value.voice) &&
    typeof value.twilioWhatsapp === 'string' &&
    typeof value.fallback === 'string' &&
    isRecord(value.icons) &&
    Object.values(value.icons).every(isIcon)
  );
};

/**
 * Mirrors the web's `useChannelIcon` / `useChannelBrandIcon` so a given inbox
 * resolves to the same glyph name on both clients.
 */
export const resolveChannelGlyph = (
  manifest: ChannelIconManifest,
  target: ChannelIconTarget,
  brand = true,
): string | null => {
  const { medium, provider, additionalType, voiceEnabled } = target;
  let type = target.channelType ?? '';

  if (type === FACEBOOK && additionalType === 'instagram_direct_message') {
    type = INSTAGRAM;
  }

  const isTwilioWhatsapp = type === TWILIO && medium === 'whatsapp';
  const byType = brand ? manifest.brand : manifest.line;
  const byProvider = brand ? manifest.providerBrand : manifest.providerLine;

  let glyph: string | undefined = byType[type];

  if (type === EMAIL && provider && byProvider[provider]) {
    glyph = byProvider[provider];
  }

  if (isTwilioWhatsapp) {
    glyph = brand ? manifest.brand[WHATSAPP] : manifest.twilioWhatsapp;
  }

  // The web only swaps in the combined voice glyph for the monochrome icon.
  if (!brand && voiceEnabled) {
    const isWhatsapp = type === WHATSAPP || isTwilioWhatsapp;
    glyph = manifest.voice[isWhatsapp ? 'whatsapp' : 'twilio'] ?? glyph;
  }

  if (glyph && manifest.icons[glyph]) return glyph;
  // No brand logo for this channel: the web falls back to the monochrome glyph.
  if (brand) return resolveChannelGlyph(manifest, target, false);
  return manifest.icons[manifest.fallback] ? manifest.fallback : null;
};

/** Wraps Iconify data as a standalone SVG document. */
export const iconToSvg = ({ body, width, height }: IconifyIcon): string =>
  `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${width} ${height}">${body}</svg>`;
